tool_schemas.implementation:
def execute_query(workspace_id, api_key, sql, parameters=None, result_format=None, max_rows=None, max_runtime_ms=None, request_context=None, **_extra):
    import json, os, datetime, time, re, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0227000" if __import__("os").path.isdir("./environment_mix/0227000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    # helpers
    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _minute_window_start(dt):
        return dt.replace(second=0, microsecond=0)

    def _month_window_start(dt):
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _new_id(prefix):
        # ULID-like base32, enough for schema patterns
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 48 bits timestamp (ms) + 80 bits randomness => 26 chars; we will output 18+ chars
        ms = int(now.timestamp() * 1000)
        ts = ms & ((1 << 48) - 1)
        rnd = uuid.uuid4().int & ((1 << 80) - 1)
        val = (ts << 80) | rnd
        out = []
        for _ in range(26):
            out.append(alphabet[val & 31])
            val >>= 5
        return prefix + "".join(reversed(out)).rstrip("=")

    def _classify_sql(s):
        # remove leading whitespace and comments
        if not isinstance(s, str):
            return "UNKNOWN"
        x = s.lstrip()
        # strip SQL comments at start: -- ... \n or /* ... */
        while True:
            if x.startswith("--"):
                nl = x.find("\n")
                x = "" if nl == -1 else x[nl+1:].lstrip()
                continue
            if x.startswith("/*"):
                end = x.find("*/")
                x = "" if end == -1 else x[end+2:].lstrip()
                continue
            break
        m = re.match(r"(?is)^([a-z_]+)", x)
        if not m:
            return "UNKNOWN"
        kw = m.group(1).upper()
        if kw == "SELECT":
            return "SELECT"
        if kw == "INSERT":
            return "INSERT"
        if kw == "UPDATE":
            return "UPDATE"
        if kw == "DELETE":
            return "DELETE"
        if kw == "MERGE":
            return "MERGE"
        if kw in ("CREATE", "ALTER", "DROP", "TRUNCATE", "RENAME", "GRANT", "REVOKE", "COMMENT", "USE"):
            return "DDL"
        if kw == "CALL":
            return "CALL"
        return "UNKNOWN"

    # Load datastore
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    query_runs = _load("query_runs.json")
    chunks = _load("query_result_chunks.json")
    counters = _load("usage_counters.json")

    # Basic validation
    if not isinstance(workspace_id, str) or not re.match(r"^sfw_[0-9A-HJKMNP-TV-Z]{16,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "Invalid api_key.")
    if not isinstance(sql, str) or len(sql) < 1:
        return _err("VALIDATION_ERROR", "Invalid sql.")
    if parameters is not None and not isinstance(parameters, dict):
        return _err("VALIDATION_ERROR", "parameters must be an object.")
    if request_context is not None and not isinstance(request_context, dict):
        return _err("VALIDATION_ERROR", "request_context must be an object.")
    if result_format is None:
        result_format = "inline_json"
    if result_format not in ("inline_json", "chunked", "none"):
        return _err("VALIDATION_ERROR", "Invalid result_format.")
    if max_rows is not None and (not isinstance(max_rows, int) or max_rows < 1):
        return _err("VALIDATION_ERROR", "max_rows must be an integer >= 1.")
    if max_runtime_ms is not None and (not isinstance(max_runtime_ms, int) or max_runtime_ms < 1):
        return _err("VALIDATION_ERROR", "max_runtime_ms must be an integer >= 1.")

    # Authenticate by matching client-visible value: accept either id, key_prefix, or full key material.
    # Note: store only has key_hash/prefix, but contract says never check hashes; thus authenticate via id/prefix.
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break
    if key_row is None:
        # try "prefix..." from full key: use first segment before "_" or first 8 chars as prefix
        candidate_prefixes = []
        if isinstance(api_key, str):
            if "_" in api_key:
                candidate_prefixes.append(api_key.split("_", 1)[0])
            candidate_prefixes.append(api_key[:8])
        for pref in candidate_prefixes:
            for k in api_keys:
                if isinstance(k, dict) and k.get("key_prefix") == pref:
                    key_row = k
                    break
            if key_row:
                break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key.")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key revoked.")

    if key_row.get("workspace_id") != workspace_id:
        return _err("UNAUTHORIZED", "API key not authorized for this workspace.")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Enforce rate limit per minute (atomic-ish by reserving in usage_counters before creating run)
    minute_start = _minute_window_start(now)
    minute_start_iso = minute_start.isoformat()

    counter_min = None
    for c in counters:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_id") == key_row.get("id") and c.get("window_type") == "minute" and c.get("window_start") == minute_start_iso:
            counter_min = c
            break
    if counter_min is None:
        counter_min = {
            "id": _new_id("usc_"),
            "api_key_id": key_row.get("id"),
            "window_type": "minute",
            "window_start": minute_start_iso,
            "request_count": 0,
            "credits_total": 0.0,
            "created_at": now_iso,
            "updated_at": now_iso,
            "status": "open"
        }
        counters.append(counter_min)

    rate_limit = key_row.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int):
        return _err("VALIDATION_ERROR", "API key rate limit misconfigured.")
    if counter_min.get("request_count", 0) + 1 > rate_limit:
        # record attempt as a request? Realistic: do not consume quota on rejected rate-limit here.
        latency_ms = int((time.time() - t0) * 1000)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rate_limit, window="minute", retry_after_seconds=60 - now.second, latency_ms=latency_ms)

    # monthly query limit check (based on query_runs created_at in current month)
    month_start = _month_window_start(now)
    month_start_dt = month_start
    monthly_limit = key_row.get("monthly_query_limit")
    if monthly_limit is not None:
        if not isinstance(monthly_limit, int) or monthly_limit < 1:
            return _err("VALIDATION_ERROR", "API key monthly_query_limit misconfigured.")
        count_month = 0
        for r in query_runs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_row.get("id"):
                continue
            rdt = _parse_dt(r.get("created_at"))
            if rdt and rdt >= month_start_dt and rdt <= now:
                count_month += 1
        if count_month + 1 > monthly_limit:
            return _err("QUOTA_EXCEEDED", "Monthly query limit exceeded.", limit=monthly_limit, window="month")

    # Estimate credits (offline): simple heuristic
    sql_type = _classify_sql(sql)
    est_credits = 0.0
    if sql_type == "SELECT":
        est_credits = 0.01
    elif sql_type in ("INSERT", "UPDATE", "DELETE", "MERGE", "CALL"):
        est_credits = 0.02
    elif sql_type == "DDL":
        est_credits = 0.005
    else:
        est_credits = 0.01

    # monthly credits limit check via usage_counters month window
    credits_limit = key_row.get("monthly_credits_limit")
    if credits_limit is not None:
        if not (isinstance(credits_limit, int) or isinstance(credits_limit, float)) or credits_limit < 0:
            return _err("VALIDATION_ERROR", "API key monthly_credits_limit misconfigured.")
        month_start_iso = month_start.isoformat()
        counter_month = None
        for c in counters:
            if not isinstance(c, dict):
                continue
            if c.get("api_key_id") == key_row.get("id") and c.get("window_type") == "month" and c.get("window_start") == month_start_iso:
                counter_month = c
                break
        if counter_month is None:
            counter_month = {
                "id": _new_id("usc_"),
                "api_key_id": key_row.get("id"),
                "window_type": "month",
                "window_start": month_start_iso,
                "request_count": 0,
                "credits_total": 0.0,
                "created_at": now_iso,
                "updated_at": now_iso,
                "status": "open"
            }
            counters.append(counter_month)
        if float(counter_month.get("credits_total", 0.0)) + float(est_credits) > float(credits_limit):
            return _err("QUOTA_EXCEEDED", "Monthly credits limit exceeded.", limit=credits_limit, window="month")

    # Reserve capacity: increment per-minute request_count and per-month request_count pre-run
    counter_min["request_count"] = int(counter_min.get("request_count", 0)) + 1
    counter_min["updated_at"] = now_iso
    month_start_iso = month_start.isoformat()
    counter_month = None
    for c in counters:
        if isinstance(c, dict) and c.get("api_key_id") == key_row.get("id") and c.get("window_type") == "month" and c.get("window_start") == month_start_iso:
            counter_month = c
            break
    if counter_month is None:
        counter_month = {
            "id": _new_id("usc_"),
            "api_key_id": key_row.get("id"),
            "window_type": "month",
            "window_start": month_start_iso,
            "request_count": 0,
            "credits_total": 0.0,
            "created_at": now_iso,
            "updated_at": now_iso,
            "status": "open"
        }
        counters.append(counter_month)
    counter_month["request_count"] = int(counter_month.get("request_count", 0)) + 1
    counter_month["updated_at"] = now_iso
    _save("usage_counters.json", counters)

    # Create query run row in queued
    run_id = _new_id("qrr_")
    run = {
        "id": run_id,
        "workspace_id": workspace_id,
        "api_key_id": key_row.get("id"),
        "status": "queued",
        "submitted_sql": sql,
        "sql_statement_type": sql_type,
        "request_context": request_context,
        "snowflake_query_id": None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "rows_returned": None,
        "bytes_scanned": None,
        "credits_attributed": None,
        "error_code": None,
        "error_message": None,
        "result_format": result_format,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    query_runs.append(run)
    _save("query_runs.json", query_runs)

    # Enforce allowed SQL types; if not allowed -> fail run
    allowed = key_row.get("allowed_sql_types")
    if not isinstance(allowed, list):
        run["status"] = "failed"
        run["error_code"] = "POLICY_MISCONFIGURED"
        run["error_message"] = "allowed_sql_types misconfigured."
        run["finished_at"] = now_iso
        run["duration_ms"] = 0
        run["updated_at"] = now_iso
        _save("query_runs.json", query_runs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"query_run": run, "result": None, "latency_ms": latency_ms}

    if sql_type not in allowed:
        run["status"] = "failed"  # queued->failed allowed
        run["error_code"] = "NOT_ALLOWED"
        run["error_message"] = f"SQL statement type {sql_type} is not allowed for this API key."
        run["finished_at"] = now_iso
        run["duration_ms"] = 0
        run["updated_at"] = now_iso
        _save("query_runs.json", query_runs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"query_run": run, "result": None, "latency_ms": latency_ms}

    # Determine effective caps
    eff_max_rows = key_row.get("max_rows")
    if not isinstance(eff_max_rows, int) or eff_max_rows < 1 or eff_max_rows > 1000000:
        run["status"] = "failed"
        run["error_code"] = "POLICY_MISCONFIGURED"
        run["error_message"] = "max_rows misconfigured."
        run["finished_at"] = now_iso
        run["duration_ms"] = 0
        run["updated_at"] = now_iso
        _save("query_runs.json", query_runs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"query_run": run, "result": None, "latency_ms": latency_ms}

    if max_rows is not None:
        eff_max_rows = min(eff_max_rows, max_rows)

    eff_max_runtime = key_row.get("max_runtime_ms")
    if not isinstance(eff_max_runtime, int) or eff_max_runtime < 1000 or eff_max_runtime > 3600000:
        run["status"] = "failed"
        run["error_code"] = "POLICY_MISCONFIGURED"
        run["error_message"] = "max_runtime_ms misconfigured."
        run["finished_at"] = now_iso
        run["duration_ms"] = 0
        run["updated_at"] = now_iso
        _save("query_runs.json", query_runs)
        latency_ms = int((time.time() - t0) * 1000)
        return {"query_run": run, "result": None, "latency_ms": latency_ms}

    if max_runtime_ms is not None:
        eff_max_runtime = min(eff_max_runtime, max_runtime_ms)

    # Transition queued->running
    start = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    run["status"] = "running"
    run["started_at"] = start.isoformat()
    run["updated_at"] = run["started_at"]
    # simulated snowflake query id
    run["snowflake_query_id"] = "SFQ_" + uuid.uuid4().hex[:20].upper()
    _save("query_runs.json", query_runs)

    # Simulated execution respecting max_runtime_ms
    # We do NOT execute SQL; we simulate deterministic results and enforce policies.
    exec_begin = time.time()

    # simulate runtime cost proportional to sql length with floor and cap checks
    simulated_ms = min(50 + int(len(sql) * 2), 5000)
    if simulated_ms > eff_max_runtime:
        # running->cancelled allowed
        finish = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        run["status"] = "cancelled"
        run["finished_at"] = finish.isoformat()
        run["duration_ms"] = int((finish - start).total_seconds() * 1000)
        run["error_code"] = "TIMEOUT"
        run["error_message"] = "Query exceeded max_runtime_ms and was cancelled."
        run["updated_at"] = run["finished_at"]
        run["credits_attributed"] = float(est_credits)
        _save("query_runs.json", query_runs)
        # attribute credits into monthly counter even if cancelled? attribute small
        for c in counters:
            if isinstance(c, dict) and c.get("api_key_id") == key_row.get("id") and c.get("window_type") == "month" and c.get("window_start") == month_start_iso:
                c["credits_total"] = float(c.get("credits_total", 0.0)) + float(est_credits)
                c["updated_at"] = run["updated_at"]
                break
        _save("usage_counters.json", counters)
        latency_ms = int((time.time() - t0) * 1000)
        return {"query_run": run, "result": None, "latency_ms": latency_ms}

    # "sleep" a tiny amount to show latency without blocking too long
    time.sleep(min(simulated_ms / 1000.0, 0.05))

    # produce simulated results
    rows = []
    rows_returned = 0
    if sql_type == "SELECT":
        # determine desired rows from parameters: {"_rows": N} if present
        desired = None
        if isinstance(parameters, dict):
            v = parameters.get("_rows")
            if isinstance(v, int) and v >= 0:
                desired = v
        if desired is None:
            desired = min(10, eff_max_rows)
        if desired > eff_max_rows:
            # policy failure: would exceed max_rows
            finish = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            run["status"] = "failed"  # running->failed allowed
            run["finished_at"] = finish.isoformat()
            run["duration_ms"] = int((finish - start).total_seconds() * 1000)
            run["error_code"] = "MAX_ROWS_EXCEEDED"
            run["error_message"] = f"Query would return {desired} rows, exceeding max_rows={eff_max_rows}."
            run["rows_returned"] = eff_max_rows
            run["credits_attributed"] = float(est_credits)
            run["updated_at"] = run["finished_at"]
            _save("query_runs.json", query_runs)
            for c in counters:
                if isinstance(c, dict) and c.get("api_key_id") == key_row.get("id") and c.get("window_type") == "month" and c.get("window_start") == month_start_iso:
                    c["credits_total"] = float(c.get("credits_total", 0.0)) + float(est_credits)
                    c["updated_at"] = run["updated_at"]
                    break
            _save("usage_counters.json", counters)
            latency_ms = int((time.time() - t0) * 1000)
            return {"query_run": run, "result": None, "latency_ms": latency_ms}

        rows_returned = int(desired)
        # deterministic payload
        for i in range(rows_returned):
            rows.append({"row_number": i + 1, "workspace_id": workspace_id, "statement_type": sql_type})

    # Persist results based on format
    result = None
    if result_format == "inline_json":
        if sql_type == "SELECT":
            result = {"rows": rows, "row_count": rows_returned}
        else:
            result = {"rows": [], "row_count": 0}
    elif result_format == "chunked":
        if sql_type == "SELECT" and rows_returned > 0:
            # chunk size 1000
            chunk_size = 1000
            chunk_index = 0
            for i in range(0, rows_returned, chunk_size):
                payload = rows[i:i + chunk_size]
                ch = {
                    "id": _new_id("qrc_"),
                    "query_run_id": run_id,
                    "chunk_index": chunk_index,
                    "row_count": len(payload),
                    "payload_json": payload,
                    "external_uri": None,
                    "content_sha256": None,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                    "status": "available"
                }
                # enforce uniqueness (query_run_id, chunk_index)
                if any(isinstance(existing, dict) and existing.get("query_run_id") == run_id and existing.get("chunk_index") == chunk_index for existing in chunks):
                    run["status"] = "failed"
                    run["error_code"] = "CHUNK_CONFLICT"
                    run["error_message"] = "Result chunk conflict."
                    break
                chunks.append(ch)
                chunk_index += 1
            _save("query_result_chunks.json", chunks)
            result = {"chunked": True, "query_run_id": run_id, "chunks": [{"id": c["id"], "chunk_index": c["chunk_index"], "row_count": c["row_count"]} for c in chunks if c.get("query_run_id") == run_id and c.get("status") == "available"]}
        else:
            result = {"chunked": True, "query_run_id": run_id, "chunks": []}
    else:  # none
        result = None

    # Finish run (running->succeeded or ->failed if chunk conflict)
    finish = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    if run["status"] == "running":
        run["status"] = "succeeded"
        run["error_code"] = None
        run["error_message"] = None
    run["finished_at"] = finish.isoformat()
    run["duration_ms"] = int((finish - start).total_seconds() * 1000)
    run["rows_returned"] = rows_returned if sql_type == "SELECT" else 0
    run["credits_attributed"] = float(est_credits)
    run["updated_at"] = run["finished_at"]

    # update api key last_used_at
    key_row["last_used_at"] = run["finished_at"]
    key_row["updated_at"] = run["finished_at"]

    # attribute credits to month counter
    for c in counters:
        if isinstance(c, dict) and c.get("api_key_id") == key_row.get("id") and c.get("window_type") == "month" and c.get("window_start") == month_start_iso:
            c["credits_total"] = float(c.get("credits_total", 0.0)) + float(est_credits)
            c["updated_at"] = run["updated_at"]
            break

    _save("query_runs.json", query_runs)
    _save("api_keys.json", api_keys)
    _save("usage_counters.json", counters)

    latency_ms = int((time.time() - t0) * 1000)
    return {"query_run": run, "result": result, "latency_ms": latency_ms}

def list_workspaces(api_key, status=None, name_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0227000" if __import__("os").path.isdir("./environment_mix/0227000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    query_runs = _load("query_runs.json")  # for audit dynamics

    # validate
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "Invalid api_key.")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if name_prefix is not None and (not isinstance(name_prefix, str) or len(name_prefix) < 1):
        return _err("VALIDATION_ERROR", "Invalid name_prefix.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if cursor is not None and (not isinstance(cursor, str) or len(cursor) < 1):
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # authenticate: accept id or key_prefix
    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and (k.get("id") == api_key or k.get("key_prefix") == api_key):
            key_row = k
            break
    if key_row is None:
        # best effort prefix
        pref = api_key.split("_", 1)[0] if "_" in api_key else api_key[:8]
        for k in api_keys:
            if isinstance(k, dict) and k.get("key_prefix") == pref:
                key_row = k
                break
    if key_row is None or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid or revoked API key.")

    # visible scope: only the workspace attached to this api key (no org model in schema)
    ws_id = key_row.get("workspace_id")
    visible = [w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id]

    # filter
    if status is not None:
        visible = [w for w in visible if w.get("status") == status]
    if name_prefix is not None:
        p = name_prefix.lower()
        visible = [w for w in visible if isinstance(w.get("name"), str) and w["name"].lower().startswith(p)]

    # order by created_at desc
    def _dt_key(w):
        v = w.get("created_at")
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00")) if isinstance(v, str) else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    visible.sort(key=_dt_key, reverse=True)

    # cursor is base64 of integer offset
    offset = 0
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(visible)
    page = visible[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    # Observable dynamics: record a read as a query_run ledger entry (system/internal, no api_key_id)
    # This schema has no request log; query_runs exists, so append an audit row with result_format='none'.
    run = {
        "id": "qrr_read_" + str(int(time.time() * 1000)),
        "workspace_id": ws_id,
        "api_key_id": key_row.get("id"),
        "status": "succeeded",
        "submitted_sql": "/* list_workspaces */",
        "sql_statement_type": "UNKNOWN",
        "request_context": {"endpoint": "list_workspaces"},
        "snowflake_query_id": None,
        "started_at": now,
        "finished_at": now,
        "duration_ms": 0,
        "rows_returned": len(page),
        "bytes_scanned": 0,
        "credits_attributed": 0.0,
        "error_code": None,
        "error_message": None,
        "result_format": "none",
        "created_at": now,
        "updated_at": now
    }
    query_runs.append(run)
    _save("query_runs.json", query_runs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "workspaces": page,
        "pagination": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
        "latency_ms": latency_ms
    }

def create_workspace(api_key, name, snowflake_account, snowflake_region, default_warehouse, default_database, default_schema, auth_method, auth_secret_ref, status=None, network_policy=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0227000" if __import__("os").path.isdir("./environment_mix/0227000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    # ------------------------- Validation -------------------------
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string with minLength 8", field="api_key")
    if not isinstance(name, str) or not (1 <= len(name) <= 200):
        return _err("VALIDATION_ERROR", "name must be a non-empty string with maxLength 200", field="name")

    def _req_str(field, v):
        if not isinstance(v, str) or len(v) < 1:
            return _err("VALIDATION_ERROR", f"{field} must be a non-empty string", field=field)
        return None

    for field, v in [
        ("snowflake_account", snowflake_account),
        ("snowflake_region", snowflake_region),
        ("default_warehouse", default_warehouse),
        ("default_database", default_database),
        ("default_schema", default_schema),
        ("auth_secret_ref", auth_secret_ref),
    ]:
        e = _req_str(field, v)
        if e:
            return e

    if auth_method not in ("password", "key_pair", "oauth"):
        return _err("VALIDATION_ERROR", "auth_method must be one of: password, key_pair, oauth", field="auth_method")

    if status is None:
        status = "active"
    if status not in ("active", "suspended"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended", field="status")

    if network_policy is not None and (not isinstance(network_policy, str) or len(network_policy) < 1):
        return _err("VALIDATION_ERROR", "network_policy must be a non-empty string when provided", field="network_policy")

    # Reject obvious control chars/newlines in key string fields
    _ctl = re.compile(r"[\x00-\x08\x0B\x0C\x0E-\x1F]")
    for field, v in [
        ("name", name),
        ("snowflake_account", snowflake_account),
        ("snowflake_region", snowflake_region),
        ("default_warehouse", default_warehouse),
        ("default_database", default_database),
        ("default_schema", default_schema),
        ("auth_secret_ref", auth_secret_ref),
    ] + ([("network_policy", network_policy)] if network_policy is not None else []):
        if isinstance(v, str) and (_ctl.search(v) or "\n" in v or "\r" in v):
            return _err("VALIDATION_ERROR", f"{field} contains invalid control characters", field=field)

    # ------------------------- Load store -------------------------
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")

    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(workspaces, list):
        workspaces = []

    # ------------------------- Authenticate (explicit credential param) -------------------------
    # Per contract: match credential by client-visible value or id; never compare to key_hash.
    # In this datastore, the only client-visible "value" we can accept is the api_keys.id itself.
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break

    if key_row is None:
        # No valid credential to authorize workspace creation
        # (There is no "internal trusted caller" path for this endpoint in the rules/schema.)
        # Still record the request if a request log existed; schema does not declare one.
        return _err("UNAUTHORIZED", "Invalid API key.")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked; authentication rejected.", api_key_status=key_row.get("status"))

    # Workspace referenced by the key (authorization context); must exist and be active
    parent_ws_id = key_row.get("workspace_id")
    parent_ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == parent_ws_id:
            parent_ws = w
            break
    if parent_ws is None:
        return _err("UNAUTHORIZED", "API key is not associated with a valid workspace.", workspace_id=parent_ws_id)
    if parent_ws.get("status") != "active":
        return _err(
            "UNAUTHORIZED",
            "Workspace is not active for this API key; operation not permitted.",
            workspace_status=parent_ws.get("status"),
            rule="Caller API key must belong to an active workspace."
        )

    # ------------------------- Constraints -------------------------
    # unique(name)
    for w in workspaces:
        if isinstance(w, dict) and w.get("name") == name:
            return _err("CONFLICT", "Workspace name must be unique.", field="name")

    # auth_secret_ref non-empty already validated

    # ------------------------- Create workspace row -------------------------
    def _new_id(prefix):
        # ULID-like (not strictly ULID) but stable prefix as in store examples
        # Use time component + hex randomness
        ts = int(now.timestamp() * 1000)
        rnd = os.urandom(10).hex()
        return f"{prefix}_{ts:x}{rnd}"[:30]  # keep reasonably short; store uses ~26-30 chars

    ws_id = _new_id("sfw")

    ws_row = {
        "id": ws_id,
        "name": name,
        "status": status,
        "snowflake_account": snowflake_account,
        "snowflake_region": snowflake_region,
        "default_warehouse": default_warehouse,
        "default_database": default_database,
        "default_schema": default_schema,
        "auth_method": auth_method,
        "auth_secret_ref": auth_secret_ref,
        "network_policy": network_policy if network_policy is not None else None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Persist
    workspaces.append(ws_row)
    _save("workspaces.json", workspaces)

    # Update key last_used_at / updated_at since it successfully authenticated for a privileged action
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    # write-through
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    # No request/audit log collection declared in schema; nothing else to persist.

    return {
        "workspace": ws_row,
        "meta": {
            "latency_ms": _lat_ms(),
            "authenticated_api_key_id": key_row.get("id"),
            "authorization_workspace_id": parent_ws.get("id"),
        },
    }

def update_workspace(api_key, workspace_id, name=None, status=None, snowflake_account=None, snowflake_region=None, default_warehouse=None, default_database=None, default_schema=None, auth_method=None, auth_secret_ref=None, network_policy=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0227000" if __import__("os").path.isdir("./environment_mix/0227000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat()

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    query_runs = _load("query_runs.json")

    # validate
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "Invalid api_key.")
    if not isinstance(workspace_id, str) or not re.match(r"^sfw_[0-9A-HJKMNP-TV-Z]{16,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if name is not None and (not isinstance(name, str) or len(name) < 1 or len(name) > 200):
        return _err("VALIDATION_ERROR", "Invalid name.")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.")
    for fld, val in [("snowflake_account", snowflake_account), ("snowflake_region", snowflake_region),
                     ("default_warehouse", default_warehouse), ("default_database", default_database),
                     ("default_schema", default_schema), ("auth_secret_ref", auth_secret_ref)]:
        if val is not None and (not isinstance(val, str) or len(val) < 1):
            return _err("VALIDATION_ERROR", f"Invalid {fld}.")
    if auth_method is not None and auth_method not in ("password", "key_pair", "oauth"):
        return _err("VALIDATION_ERROR", "Invalid auth_method.")
    if network_policy is not None and (not isinstance(network_policy, str) or len(network_policy) < 1):
        return _err("VALIDATION_ERROR", "Invalid network_policy.")

    # authenticate
    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and (k.get("id") == api_key or k.get("key_prefix") == api_key):
            key_row = k
            break
    if key_row is None:
        pref = api_key.split("_", 1)[0] if "_" in api_key else api_key[:8]
        for k in api_keys:
            if isinstance(k, dict) and k.get("key_prefix") == pref:
                key_row = k
                break
    if key_row is None or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid or revoked API key.")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.")

    # authorization scope: only update workspaces visible to the key (same workspace)
    if key_row.get("workspace_id") != workspace_id:
        return _err("UNAUTHORIZED", "Not authorized for this workspace.")

    # refuse updates to deleted workspaces
    if ws.get("status") == "deleted":
        # if no fields provided, allow a no-op "read"
        if all(v is None for v in [name, status, snowflake_account, snowflake_region, default_warehouse, default_database, default_schema, auth_method, auth_secret_ref, network_policy]):
            latency_ms = int((time.time() - t0) * 1000)
            return {"workspace": ws, "latency_ms": latency_ms}
        return _err("INVALID_TRANSITION", "Cannot update a deleted workspace.")

    # unique(name) if changed
    if name is not None and name != ws.get("name"):
        for w in workspaces:
            if isinstance(w, dict) and w.get("name") == name:
                return _err("CONFLICT", "Workspace name already exists.", field="name")

    # lifecycle transitions
    allowed_transitions = {
        "active": set(["suspended", "deleted"]),
        "suspended": set(["active", "deleted"]),
        "deleted": set([])
    }
    if status is not None and status != ws.get("status"):
        cur = ws.get("status")
        if cur not in allowed_transitions or status not in allowed_transitions[cur]:
            return _err("INVALID_TRANSITION", f"Transition {cur} -> {status} is not permitted.")
        ws["status"] = status
        # soft delete should revoke associated api_keys
        if status == "deleted":
            for k in api_keys:
                if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active":
                    k["status"] = "revoked"
                    k["updated_at"] = now

    # field updates
    if snowflake_account is not None:
        ws["snowflake_account"] = snowflake_account
    if snowflake_region is not None:
        ws["snowflake_region"] = snowflake_region
    if default_warehouse is not None:
        ws["default_warehouse"] = default_warehouse
    if default_database is not None:
        ws["default_database"] = default_database
    if default_schema is not None:
        ws["default_schema"] = default_schema
    if auth_method is not None:
        ws["auth_method"] = auth_method
    if auth_secret_ref is not None:
        ws["auth_secret_ref"] = auth_secret_ref
    if network_policy is not None:
        ws["network_policy"] = {"id": network_policy}
    if name is not None:
        ws["name"] = name

    if not isinstance(ws.get("auth_secret_ref"), str) or len(ws["auth_secret_ref"]) < 1:
        return _err("VALIDATION_ERROR", "auth_secret_ref must be non-empty.")

    ws["updated_at"] = now
    _save("workspaces.json", workspaces)
    _save("api_keys.json", api_keys)

    # Observable dynamics: append audit row
    audit = {
        "id": "qrr_audit_" + str(int(time.time() * 1000)),
        "workspace_id": workspace_id,
        "api_key_id": key_row.get("id"),
        "status": "succeeded",
        "submitted_sql": "/* update_workspace */",
        "sql_statement_type": "UNKNOWN",
        "request_context": {"endpoint": "update_workspace"},
        "snowflake_query_id": None,
        "started_at": now,
        "finished_at": now,
        "duration_ms": 0,
        "rows_returned": 1,
        "bytes_scanned": 0,
        "credits_attributed": 0.0,
        "error_code": None,
        "error_message": None,
        "result_format": "none",
        "created_at": now,
        "updated_at": now
    }
    query_runs.append(audit)
    _save("query_runs.json", query_runs)

    latency_ms = int((time.time() - t0) * 1000)
    return {"workspace": ws, "latency_ms": latency_ms}

def create_api_key(api_key, workspace_id, name, allowed_sql_types, max_rows, max_runtime_ms, rate_limit_per_minute, monthly_query_limit=None, monthly_credits_limit=None, **_extra):
    import json, os, datetime, time, re, secrets, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0227000" if __import__("os").path.isdir("./environment_mix/0227000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, credential_id, status, error_code=None):
        # No request-log/audit collection defined in schema; nothing to persist.

        return

    def _is_str(x):
        return isinstance(x, str)

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def _ulid_like(prefix, nmin=16):
        if not _is_str(prefix):
            return False
        pat = r"^[0-9A-HJKMNP-TV-Z]{%d,}$" % nmin
        return re.match(pat, prefix) is not None

    def _gen_ulid(prefix):
        # Vendor says ULID-like; implement as prefix + random Crockford base32.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _hash_key_material(plain):
        # Not used for auth comparison; stored as hash for realism.
        return hashlib.sha256(plain.encode("utf-8")).hexdigest()

    # Validate inputs
    if not _is_str(api_key) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")
    if not _is_str(workspace_id) or re.match(r"^sfw_[0-9A-HJKMNP-TV-Z]{16,}$", workspace_id) is None:
        return _err("VALIDATION_ERROR", "workspace_id is invalid")
    if not _is_str(name) or not (1 <= len(name) <= 200):
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 chars")
    if not isinstance(allowed_sql_types, list) or len(allowed_sql_types) < 1 or not all(isinstance(x, str) for x in allowed_sql_types):
        return _err("VALIDATION_ERROR", "allowed_sql_types must be a non-empty array of strings")
    allowed_enum_tool = {"SELECT", "INSERT", "UPDATE", "DELETE", "MERGE", "CREATE", "ALTER", "DROP", "TRUNCATE", "CALL", "EXPLAIN", "DESCRIBE", "SHOW", "USE", "OTHER"}
    if any(x not in allowed_enum_tool for x in allowed_sql_types):
        return _err("VALIDATION_ERROR", "allowed_sql_types contains invalid value(s)", allowed=list(sorted(allowed_enum_tool)))
    if not isinstance(max_rows, int) or isinstance(max_rows, bool) or max_rows < 1:
        return _err("VALIDATION_ERROR", "max_rows must be an integer >= 1")
    # Schema constraint max_rows between 1 and 1000000
    if max_rows > 1000000:
        return _err("VALIDATION_ERROR", "max_rows must be <= 1000000")
    if not isinstance(max_runtime_ms, int) or isinstance(max_runtime_ms, bool) or max_runtime_ms < 1:
        return _err("VALIDATION_ERROR", "max_runtime_ms must be an integer >= 1")
    if max_runtime_ms < 1000 or max_runtime_ms > 3600000:
        return _err("VALIDATION_ERROR", "max_runtime_ms must be between 1000 and 3600000")
    if not isinstance(rate_limit_per_minute, int) or isinstance(rate_limit_per_minute, bool) or rate_limit_per_minute < 1:
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer >= 1")
    if rate_limit_per_minute < 1 or rate_limit_per_minute > 6000:
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 6000")
    if monthly_query_limit is not None:
        if not isinstance(monthly_query_limit, int) or isinstance(monthly_query_limit, bool) or monthly_query_limit < 1:
            return _err("VALIDATION_ERROR", "monthly_query_limit must be an integer >= 1 or null")
    if monthly_credits_limit is not None:
        if not _is_num(monthly_credits_limit) or monthly_credits_limit < 0:
            return _err("VALIDATION_ERROR", "monthly_credits_limit must be a number >= 0 or null")

    # Load datastore
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    # Authenticate provided api_key: match by client-visible value OR id.
    # Since store only has key_prefix and key_hash, we authenticate by:
    # - exact match on id, OR
    # - match on key_prefix (common pattern: prefix is visible), OR
    # - match on full plaintext key prefix before "_" if caller passed such a token.
    presented = api_key
    presented_prefix = None
    if _is_str(presented):
        # Common shape: "<prefix>_<secret>" or "sfk_<...>" etc.
        if "_" in presented:
            presented_prefix = presented.split("_", 1)[0]
        else:
            presented_prefix = presented[:8]

    caller_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == presented:
            caller_key = k
            break
        if presented_prefix and k.get("key_prefix") == presented_prefix:
            caller_key = k
            break
        if k.get("key_prefix") == presented:
            caller_key = k
            break

    if caller_key is None or caller_key.get("status") != "active":
        _log("create_api_key", None, "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    # Authorize against workspace_id: must match caller_key.workspace_id
    if caller_key.get("workspace_id") != workspace_id:
        _log("create_api_key", caller_key.get("id"), "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key not authorized for this workspace")

    # Workspace must exist and be active (refuse suspended/deleted)
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("create_api_key", caller_key.get("id"), "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log("create_api_key", caller_key.get("id"), "error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Workspace is not active; cannot create API keys", workspace_status=ws.get("status"))

    # Enforce unique(workspace_id, key_prefix)
    # Generate a plaintext key: prefix identifies it for logs. Use "sk_" prefix token.
    # Ensure generated key_prefix unique within workspace.
    tries = 0
    new_prefix = None
    while tries < 50:
        tries += 1
        # 8 chars is plenty; keep alnum for prefix
        new_prefix = secrets.token_hex(4)  # 8 hex chars
        if not any(isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("key_prefix") == new_prefix for r in api_keys):
            break
        new_prefix = None
    if new_prefix is None:
        _log("create_api_key", caller_key.get("id"), "error", error_code="CONFLICT")
        return _err("CONFLICT", "Could not allocate a unique key_prefix for this workspace")

    # Create new api key record
    now = _now()
    new_id = _gen_ulid("sfk_")
    # Ensure id uniqueness
    while any(isinstance(r, dict) and r.get("id") == new_id for r in api_keys):
        new_id = _gen_ulid("sfk_")

    plaintext_key = f"{new_prefix}_{secrets.token_urlsafe(24)}"
    new_row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "key_hash": _hash_key_material(plaintext_key),
        "key_prefix": new_prefix,
        "name": name,
        "status": "active",
        # Map tool enums to schema enums (DDL vs CREATE/ALTER/DROP/TRUNCATE/etc, OTHER->UNKNOWN unsupported)
        "allowed_sql_types": None,
        "max_rows": int(max_rows),
        "max_runtime_ms": int(max_runtime_ms),
        "rate_limit_per_minute": int(rate_limit_per_minute),
        "monthly_query_limit": int(monthly_query_limit) if monthly_query_limit is not None else None,
        "monthly_credits_limit": float(monthly_credits_limit) if monthly_credits_limit is not None else None,
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Translate allowed_sql_types to schema enum set: SELECT/INSERT/UPDATE/DELETE/MERGE/DDL/CALL
    # Tool allows many DDL-ish verbs; collapse to DDL. OTHER not representable -> reject.
    schema_allowed = set()
    for t in allowed_sql_types:
        if t in {"SELECT", "INSERT", "UPDATE", "DELETE", "MERGE", "CALL"}:
            schema_allowed.add(t)
        elif t in {"CREATE", "ALTER", "DROP", "TRUNCATE", "EXPLAIN", "DESCRIBE", "SHOW", "USE"}:
            schema_allowed.add("DDL")
        elif t == "OTHER":
            return _err("VALIDATION_ERROR", "allowed_sql_types contains OTHER, which is not supported by this backend schema")
        else:
            return _err("VALIDATION_ERROR", "allowed_sql_types contains invalid value")
    new_row["allowed_sql_types"] = sorted(schema_allowed)

    api_keys.append(new_row)
    _save("api_keys.json", api_keys)

    # Update caller last_used_at? This is management call; record only on success.
    caller_key["last_used_at"] = now
    caller_key["updated_at"] = now
    _save("api_keys.json", api_keys)

    _log("create_api_key", caller_key.get("id"), "success")
    return {
        "api_key": new_row,
        "plaintext_api_key": plaintext_key,
        "warning": "The plaintext_api_key is shown only once and cannot be retrieved later."
    }

def update_api_key(api_key, api_key_id, name=None, status=None, allowed_sql_types=None, max_rows=None, max_runtime_ms=None, rate_limit_per_minute=None, monthly_query_limit=None, monthly_credits_limit=None, **_extra):
    import json, os, datetime, time, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0227000" if __import__("os").path.isdir("./environment_mix/0227000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now_dt.isoformat()

    # Validate required
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8", field="api_key")
    if not isinstance(api_key_id, str) or re.match(r"^sfk_[0-9A-HJKMNP-TV-Z]{16,}$", api_key_id) is None:
        return _err("VALIDATION_ERROR", "api_key_id is invalid", field="api_key_id")

    # Validate optionals
    if name is not None and (not isinstance(name, str) or not (1 <= len(name) <= 200)):
        return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 chars", field="name")

    if status is not None and status not in ("active", "revoked"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'revoked'", field="status")

    # Tool's enum differs from backend; map tool values to backend allowed_sql_types
    # Backend allowed_sql_types enum: SELECT, INSERT, UPDATE, DELETE, MERGE, DDL, CALL
    # Tool allows many granular tokens -> map DDL-ish and other introspection into DDL; unknowns into DDL/SELECT is unsafe; use DDL for DDL tokens; reject OTHER.
    map_to_backend = {
        "SELECT": "SELECT",
        "INSERT": "INSERT",
        "UPDATE": "UPDATE",
        "DELETE": "DELETE",
        "MERGE": "MERGE",
        "CALL": "CALL",
        "CREATE": "DDL",
        "ALTER": "DDL",
        "DROP": "DDL",
        "TRUNCATE": "DDL",
        "EXPLAIN": "DDL",
        "DESCRIBE": "DDL",
        "SHOW": "DDL",
        "USE": "DDL",
    }
    tool_allowed_enum = set(map_to_backend.keys()) | {"OTHER"}

    if allowed_sql_types is not None:
        if not isinstance(allowed_sql_types, list) or len(allowed_sql_types) < 1 or not all(isinstance(x, str) for x in allowed_sql_types):
            return _err("VALIDATION_ERROR", "allowed_sql_types must be a non-empty array of strings", field="allowed_sql_types")
        bad = [x for x in allowed_sql_types if x not in tool_allowed_enum]
        if bad:
            return _err("VALIDATION_ERROR", "allowed_sql_types contains invalid value(s)", field="allowed_sql_types", invalid=bad, allowed=sorted(tool_allowed_enum))
        if "OTHER" in allowed_sql_types:
            return _err("VALIDATION_ERROR", "allowed_sql_types cannot include OTHER for this backend", field="allowed_sql_types")

    if max_rows is not None:
        if not isinstance(max_rows, int) or isinstance(max_rows, bool) or not (1 <= max_rows <= 1000000):
            return _err("VALIDATION_ERROR", "max_rows must be an integer between 1 and 1000000", field="max_rows")

    if max_runtime_ms is not None:
        if (not isinstance(max_runtime_ms, int)) or isinstance(max_runtime_ms, bool) or not (1000 <= max_runtime_ms <= 3600000):
            return _err("VALIDATION_ERROR", "max_runtime_ms must be an integer between 1000 and 3600000", field="max_runtime_ms")

    if rate_limit_per_minute is not None:
        if (not isinstance(rate_limit_per_minute, int)) or isinstance(rate_limit_per_minute, bool) or not (1 <= rate_limit_per_minute <= 6000):
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer between 1 and 6000", field="rate_limit_per_minute")

    if monthly_query_limit is not None:
        if monthly_query_limit is not None and ((not isinstance(monthly_query_limit, int)) or isinstance(monthly_query_limit, bool) or monthly_query_limit < 1):
            return _err("VALIDATION_ERROR", "monthly_query_limit must be null or an integer >= 1", field="monthly_query_limit")

    if monthly_credits_limit is not None:
        if monthly_credits_limit is not None and ((not isinstance(monthly_credits_limit, (int, float))) or isinstance(monthly_credits_limit, bool) or monthly_credits_limit < 0):
            return _err("VALIDATION_ERROR", "monthly_credits_limit must be null or a number >= 0", field="monthly_credits_limit")

    # Authenticate caller key (explicit credential param): match by id or key_prefix; must be active
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    caller = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            caller = k
            break
    if caller is None:
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            kp = k.get("key_prefix")
            if isinstance(kp, str) and api_key.startswith(kp):
                caller = k
                break
    if caller is None:
        return _err("UNAUTHORIZED", "API key not recognized.", field="api_key")
    if caller.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", field="api_key", key_status=caller.get("status"))

    # Locate target key
    target_idx = None
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key_id:
            target_idx = i
            break
    if target_idx is None:
        return _err("NOT_FOUND", "API key not found.", api_key_id=api_key_id)

    target = api_keys[target_idx]

    # Authorization: allow management within same workspace only
    if caller.get("workspace_id") != target.get("workspace_id"):
        return _err("UNAUTHORIZED", "Caller is not authorized to manage this API key.", api_key_id=api_key_id)

    # Enforce lifecycle transitions
    if status is not None:
        cur = target.get("status")
        if cur == "revoked" and status == "active":
            return _err("INVALID_TRANSITION", "Cannot reactivate a revoked key (revoked -> active not permitted).", from_status=cur, to_status=status)
        if cur == "active" and status == "revoked":
            pass
        elif cur == status:
            # idempotent; ok
            pass
        else:
            return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=cur, to_status=status)

    # Apply mutations (NO SUCCESS WITHOUT EFFECT: if nothing changes, treat as no-op but still return updated record;
    # however a mutation request with no fields besides required should be validation error)
    any_field_provided = any(v is not None for v in [name, status, allowed_sql_types, max_rows, max_runtime_ms, rate_limit_per_minute, monthly_query_limit, monthly_credits_limit])
    if not any_field_provided:
        return _err("VALIDATION_ERROR", "No updatable fields provided.", field="body")

    changed = False

    if name is not None and name != target.get("name"):
        target["name"] = name
        changed = True

    if status is not None and status != target.get("status"):
        target["status"] = status
        changed = True

    if allowed_sql_types is not None:
        mapped = []
        for x in allowed_sql_types:
            mapped.append(map_to_backend.get(x))
        # dedupe while preserving order
        dedup = []
        seen = set()
        for x in mapped:
            if x not in seen:
                seen.add(x)
                dedup.append(x)
        if dedup != target.get("allowed_sql_types"):
            target["allowed_sql_types"] = dedup
            changed = True

    if max_rows is not None and max_rows != target.get("max_rows"):
        target["max_rows"] = max_rows
        changed = True

    if max_runtime_ms is not None and max_runtime_ms != target.get("max_runtime_ms"):
        target["max_runtime_ms"] = max_runtime_ms
        changed = True

    if rate_limit_per_minute is not None and rate_limit_per_minute != target.get("rate_limit_per_minute"):
        target["rate_limit_per_minute"] = rate_limit_per_minute
        changed = True

    # Allow clearing limits by explicit null (None) for these optional fields (tool description says supported "if supported by backend"; backend schema allows null)
    if monthly_query_limit is not None or monthly_query_limit is None:
        # Only apply if caller explicitly passed it: but in Python signature, default is None; can't distinguish omitted vs null.
        # Here: treat explicit None as "clear" only if _extra indicates it, otherwise avoid unintended clearing.
        # However tool contract uses JSON; passing null will arrive as None, indistinguishable from omission.
        # To stay safe and consistent: only update these if provided via _extra flag "__provided_fields".
        provided = _extra.get("__provided_fields")
        if isinstance(provided, list) and "monthly_query_limit" in provided:
            if monthly_query_limit != target.get("monthly_query_limit"):
                target["monthly_query_limit"] = monthly_query_limit
                changed = True

    if monthly_credits_limit is not None or monthly_credits_limit is None:
        provided = _extra.get("__provided_fields")
        if isinstance(provided, list) and "monthly_credits_limit" in provided:
            if monthly_credits_limit != target.get("monthly_credits_limit"):
                target["monthly_credits_limit"] = monthly_credits_limit
                changed = True

    if changed:
        target["updated_at"] = now_iso
        # Update caller last_used_at as successful management action
        caller_id = caller.get("id")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == caller_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso if isinstance(k.get("updated_at"), str) else now_iso
                break
        try:
            _save("api_keys.json", api_keys)
        except Exception:
            return _err("CONFLICT", "Failed to persist API key update (datastore write error).")
    else:
        # No actual changes requested (values identical); return current row (idempotent update)
        pass

    return {
        "api_key": api_keys[target_idx],
        "meta": {
            "latency_ms": int((time.time() - _t0) * 1000),
            "updated": changed,
        },
    }

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0227000" if __import__("os").path.isdir("./environment_mix/0227000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _log(endpoint, credential_id, status_s, error_code=None):
        return

    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    usage = _load("usage_counters.json")
    query_runs = _load("query_runs.json")

    presented = api_key
    presented_prefix = presented.split("_", 1)[0] if "_" in presented else presented[:8]

    key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == presented or k.get("key_prefix") == presented or k.get("key_prefix") == presented_prefix:
            key = k
            break

    if key is None:
        _log("get_current_identity", None, "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unknown API key")

    if key.get("status") != "active":
        _log("get_current_identity", key.get("id"), "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Revoked API key")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == key.get("workspace_id")), None)
    if ws is None:
        _log("get_current_identity", key.get("id"), "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    now = _now_dt()
    minute_start = now.replace(second=0, microsecond=0)
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _parse_iso_z(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Rate-limit consumption snapshot: use usage_counters minute window if exists, else compute from query_runs.
    minute_row = None
    for r in usage:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") == key.get("id") and r.get("window_type") == "minute":
            ts = _parse_iso_z(r.get("window_start"))
            if ts == minute_start:
                minute_row = r
                break
    if minute_row is None:
        # fallback compute from query_runs
        cnt = 0
        for qr in query_runs:
            if not isinstance(qr, dict):
                continue
            if qr.get("api_key_id") != key.get("id"):
                continue
            t = _parse_iso_z(qr.get("created_at"))
            if t is not None and t >= minute_start and t < (minute_start + datetime.timedelta(minutes=1)):
                cnt += 1
        minute_used = cnt
    else:
        minute_used = int(minute_row.get("request_count") or 0)

    # Monthly usage snapshot
    month_row = None
    for r in usage:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") == key.get("id") and r.get("window_type") == "month":
            ts = _parse_iso_z(r.get("window_start"))
            if ts == month_start:
                month_row = r
                break
    if month_row is None:
        # fallback compute
        mcnt = 0
        credits = 0.0
        for qr in query_runs:
            if not isinstance(qr, dict):
                continue
            if qr.get("api_key_id") != key.get("id"):
                continue
            t = _parse_iso_z(qr.get("created_at"))
            if t is not None and t >= month_start and t < (month_start + datetime.timedelta(days=32)):
                if t.month == month_start.month and t.year == month_start.year:
                    mcnt += 1
                    c = qr.get("credits_attributed")
                    if isinstance(c, (int, float)) and not isinstance(c, bool):
                        credits += float(c)
        month_used = mcnt
        credits_used = credits
    else:
        month_used = int(month_row.get("request_count") or 0)
        credits_used = float(month_row.get("credits_total") or 0.0)

    # Update last_used_at for successful identity lookups
    now_iso = _now_iso()
    key["last_used_at"] = now_iso
    key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    identity = {
        "api_key": {
            "id": key.get("id"),
            "workspace_id": key.get("workspace_id"),
            "key_prefix": key.get("key_prefix"),
            "name": key.get("name"),
            "status": key.get("status"),
            "allowed_sql_types": key.get("allowed_sql_types"),
            "max_rows": key.get("max_rows"),
            "max_runtime_ms": key.get("max_runtime_ms"),
            "rate_limit_per_minute": key.get("rate_limit_per_minute"),
            "monthly_query_limit": key.get("monthly_query_limit"),
            "monthly_credits_limit": key.get("monthly_credits_limit"),
            "last_used_at": key.get("last_used_at"),
            "created_at": key.get("created_at"),
            "updated_at": key.get("updated_at"),
        },
        "workspace": {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
            "snowflake_account": ws.get("snowflake_account"),
            "snowflake_region": ws.get("snowflake_region"),
            "default_warehouse": ws.get("default_warehouse"),
            "default_database": ws.get("default_database"),
            "default_schema": ws.get("default_schema"),
            "auth_method": ws.get("auth_method"),
            "created_at": ws.get("created_at"),
            "updated_at": ws.get("updated_at"),
        },
        "consumption": {
            "minute": {
                "window_start": minute_start.isoformat() + "Z",
                "used": minute_used,
                "limit": key.get("rate_limit_per_minute"),
                "remaining": max(0, int(key.get("rate_limit_per_minute") or 0) - int(minute_used)),
            },
            "month": {
                "window_start": month_start.isoformat() + "Z",
                "queries_used": month_used,
                "queries_limit": key.get("monthly_query_limit"),
                "credits_used": credits_used,
                "credits_limit": key.get("monthly_credits_limit"),
            },
        },
    }

    _log("get_current_identity", key.get("id"), "success")
    return {"identity": identity}
